import json
true, false, null = True, False, None

MAXN = {{ vars.max_indicators | default(10) }}
# Which indicator types this run should process. Today "ip". Change the
# Configuration step to "ip,domain,url,hash" to widen it - nothing else in the
# playbook needs editing; AbuseIPDB is skipped for non-IP types automatically
# and FortiGuard handles all four.
ENABLED = "{{ vars.enabled_types | default('ip') }}".lower()

recs = [{% for r in vars.steps.Find_Blocked_IPs %}{"iri": "{{ r['@id'] }}", "ind": "{{ r.idicator | default('', true) | replace('"', '') | trim }}", "reason": "{{ r.reason | default('', true) | replace('"', '') }}", "fw": "{{ r.firewall | default('', true) | replace('"', '') }}", "ticket": "{{ r.ticketId | default('', true) | replace('"', '') }}", "origin": "{{ r.orgination | default('', true) | replace('"', '') }}", "created": "{{ r.createDate | default('', true) }}"}{% if not loop.last %}, {% endif %}{% endfor %}]

enabled_types = []
for t in ENABLED.split(","):
    t = t.strip()
    if t:
        enabled_types.append(t)

HEXCHARS = "0123456789abcdef"


def is_ipv4(s):
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        n = int(p)
        if n < 0 or n > 255:
            return False
        if len(p) > 1 and p[0] == "0":
            return False
    return True


def is_hex(s):
    low = s.lower()
    for ch in low:
        if ch not in HEXCHARS:
            return False
    return len(low) > 0


def is_hash(s):
    return len(s) in (32, 40, 64, 128) and is_hex(s)


def is_url(s):
    low = s.lower()
    return low.startswith("http://") or low.startswith("https://")


def is_domain(s):
    if "." not in s or " " in s:
        return False
    if s.endswith("."):
        return False
    labels = s.split(".")
    if len(labels) < 2:
        return False
    tld = labels[-1]
    if len(tld) < 2 or not tld.isalpha():
        return False
    for lab in labels:
        if not lab:
            return False
        for ch in lab:
            if not (ch.isalnum() or ch == "-"):
                return False
        if lab[0] == "-" or lab[-1] == "-":
            return False
    return True


def classify(s):
    """Order matters: an IP is dotted like a domain, a hash is alphanumeric."""
    if is_ipv4(s):
        return "ip"
    if is_url(s):
        return "url"
    if is_hash(s):
        return "hash"
    if is_domain(s):
        return "domain"
    return "unknown"


indicators = []
skipped = []
seen = {}
type_counts = {"ip": 0, "domain": 0, "url": 0, "hash": 0, "unknown": 0}

for r in recs:
    val = (r.get("ind") or "").strip()
    if not val:
        skipped.append({"iri": r.get("iri"), "value": "", "type": "",
                        "why": "empty indicator field"})
        continue
    kind = classify(val)
    type_counts[kind] = type_counts.get(kind, 0) + 1

    if kind == "unknown":
        skipped.append({"iri": r.get("iri"), "value": val, "type": kind,
                        "why": "not a recognised IP, domain, URL or hash"})
        continue
    if kind not in enabled_types:
        skipped.append({"iri": r.get("iri"), "value": val, "type": kind,
                        "why": "type '%s' is not enabled for this run" % kind})
        continue
    key = kind + "|" + val.lower()
    if key in seen:
        skipped.append({"iri": r.get("iri"), "value": val, "type": kind,
                        "why": "duplicate in this batch"})
        continue
    seen[key] = 1

    indicators.append({
        "iri": r.get("iri") or "",
        "value": val,
        "ip": val,
        "type": kind,
        "reason": r.get("reason") or "",
        "firewall": r.get("fw") or "",
        "ticket": r.get("ticket") or "",
        "origin": r.get("origin") or "",
        "created": r.get("created") or "",
    })
    if len(indicators) >= MAXN:
        break

# AbuseIPDB only understands IPs. FortiGuard takes every enabled type, so it
# gets the full list and the two result sets are joined back up in Evaluate.
ip_list = []
all_list = []
for i in indicators:
    all_list.append(i["value"])
    if i["type"] == "ip":
        ip_list.append(i["value"])

print(json.dumps({
    "indicators": indicators,
    "ip_list": ip_list,
    "all_list": all_list,
    "count": len(indicators),
    "ip_count": len(ip_list),
    "skipped": skipped,
    "fetched": len(recs),
    "max_indicators": MAXN,
    "enabled_types": enabled_types,
    "type_counts": type_counts,
}))

import json, time
true, false, null = True, False, None

THRESHOLD = {{ vars.abuse_threshold | default(10) }}
FG_OVERRIDE = "{{ vars.fortiguard_override | default('yes') }}".lower()
MODE = "{{ vars.containment_mode | default('SIMULATED') }}"

ext = {{ vars.steps.Extract_Indicators.data['code_output'] }}
inds = ext.get("indicators") or []

ab = [{% for e in vars.steps.Enrich_AbuseIPDB %}{"ip": "{{ e.data.ipAddress | default('', true) }}", "score": {{ e.data.abuseConfidenceScore | default(0, true) }}, "reports": {{ e.data.totalReports | default(0, true) }}, "distinct": {{ e.data.numDistinctUsers | default(0, true) }}, "wl": "{{ e.data.isWhitelisted | default('', true) }}", "cc": "{{ e.data.countryCode | default('', true) }}", "isp": "{{ e.data.isp | default('', true) | replace('"', '') }}", "usage": "{{ e.data.usageType | default('', true) | replace('"', '') }}", "dom": "{{ e.data.domain | default('', true) | replace('"', '') }}", "last": "{{ e.data.lastReportedAt | default('', true) }}", "tor": "{{ e.data.isTor | default('', true) }}"}{% if not loop.last %}, {% endif %}{% endfor %}]

fg = [{% for e in vars.steps.Enrich_FortiGuard %}{"conf": "{{ e.data.confidence | default('', true) }}", "wf": "{{ e.data.wf_cate | default('', true) | replace('"', '') }}", "ioc": "{{ e.data.ioc_cate | default('', true) | replace('"', '') }}", "av": "{{ e.data.av_cate | default('', true) | replace('"', '') }}", "malware": "{{ e.data.malware_name | default('', true) | replace('"', '') }}", "tags": "{{ e.data.ioc_tags | default([], true) | join(', ') | replace('"', '') }}", "msg": "{{ e.data.message | default('', true) | replace('"', '') }}"}{% if not loop.last %}, {% endif %}{% endfor %}]


def truthy(v):
    return str(v).strip().lower() in ("true", "1", "yes")


def as_date(v):
    """Epoch float -> readable date. Anything else passes through."""
    s = str(v or "").strip()
    if not s:
        return ""
    try:
        return time.strftime("%Y-%m-%d", time.gmtime(float(s)))
    except Exception:
        return s


def fg_is_bad(f):
    """FortiGuard says malicious. Parsed BY FIELD - never substring the blob."""
    if not f:
        return False, ""
    reasons = []
    conf = str(f.get("conf") or "").strip().lower()
    if conf in ("medium", "high"):
        reasons.append("confidence=" + str(f.get("conf")))
    mal = str(f.get("malware") or "").strip()
    if mal and mal.lower() not in ("", "none", "null", "n/a"):
        reasons.append("malware=" + mal)
    ioc = str(f.get("ioc") or "").strip()
    if ioc and ioc.lower() not in ("", "none", "null", "n/a", "unknown"):
        reasons.append("ioc_cate=" + ioc)
    av = str(f.get("av") or "").strip()
    if av and av.lower() not in ("", "none", "null", "n/a", "unknown"):
        reasons.append("av_cate=" + av)
    return (len(reasons) > 0), "; ".join(reasons)


keep = []
review = []
clean = []
rows = []

# AbuseIPDB ran only over the IP subset, FortiGuard over every enabled
# indicator. Join AbuseIPDB back by address and FortiGuard by position.
ab_by_ip = {}
for a in ab:
    if a.get("ip"):
        ab_by_ip[str(a["ip"])] = a

for i in range(len(inds)):
    rec = inds[i]
    kind = rec.get("type") or "ip"
    val = rec.get("value") or rec.get("ip") or ""
    a = ab_by_ip.get(val) or {}
    f = fg[i] if i < len(fg) else {}

    raw = a.get("score")
    have_ab = (kind == "ip") and raw is not None and str(raw) != ""
    score = int(raw or 0)

    bad_fg, fg_reason = fg_is_bad(f)
    over_thresh = have_ab and score >= THRESHOLD

    reasons = []
    if kind == "ip":
        if have_ab:
            if over_thresh:
                reasons.append("AbuseIPDB %d%% at or above threshold %d%%"
                               % (score, THRESHOLD))
            else:
                reasons.append("AbuseIPDB %d%% below threshold %d%%"
                               % (score, THRESHOLD))
        else:
            reasons.append("AbuseIPDB returned no score for this IP")
    else:
        reasons.append("%s indicator - AbuseIPDB does not apply, "
                       "FortiGuard is the only source" % kind)
    if bad_fg:
        reasons.append("FortiGuard: " + fg_reason)
    elif str(f.get("msg") or ""):
        reasons.append("FortiGuard: " + str(f.get("msg")))

    # For IPs the threshold is authoritative; FortiGuard never silently
    # reverses it, it can only pull an indicator out of the removal set into
    # REVIEW so a human still decides. For non-IP types there is no AbuseIPDB
    # score at all, so FortiGuard alone decides.
    if kind == "ip":
        if over_thresh:
            verdict = "KEEP"
        elif bad_fg and FG_OVERRIDE in ("yes", "true", "1"):
            verdict = "REVIEW"
            reasons.append("held back from removal: FortiGuard still flags this IP")
        else:
            verdict = "CLEAN"
    else:
        if bad_fg:
            verdict = "KEEP"
        else:
            verdict = "CLEAN"

    if truthy(a.get("wl")):
        reasons.append("AbuseIPDB lists this IP as whitelisted")

    row = {
        "ip": val,
        "value": val,
        "type": kind,
        "iri": rec.get("iri"),
        "verdict": verdict,
        "abuse_score": score if have_ab else null,
        "abuse_applies": have_ab,
        "abuse_reports": int(a.get("reports") or 0),
        "abuse_distinct_users": int(a.get("distinct") or 0),
        "whitelisted": truthy(a.get("wl")),
        "is_tor": truthy(a.get("tor")),
        "country": a.get("cc") or "",
        "isp": a.get("isp") or "",
        "usage_type": a.get("usage") or "",
        "hostname": a.get("dom") or "",
        "last_reported": (a.get("last") or "")[:10],
        "fortiguard_confidence": f.get("conf") or "",
        "fortiguard_category": f.get("wf") or "",
        "fortiguard_malware": f.get("malware") or "",
        "fortiguard_tags": f.get("tags") or "",
        "fortiguard_flagged": bad_fg,
        "block_reason": rec.get("reason") or "",
        "firewall": rec.get("firewall") or "",
        "ticket": rec.get("ticket") or "",
        "blocked_on": as_date(rec.get("created")),
        "rationale": reasons,
    }
    rows.append(row)
    if verdict == "KEEP":
        keep.append(row)
    elif verdict == "REVIEW":
        review.append(row)
    else:
        clean.append(row)

n_total = len(rows)
n_keep = len(keep)
n_review = len(review)
n_clean = len(clean)

clean_ips = []
clean_iris = []
for r in clean:
    clean_ips.append(r["ip"])
    clean_iris.append(r["iri"])
keep_ips = []
for r in keep:
    keep_ips.append(r["ip"])
review_ips = []
for r in review:
    review_ips.append(r["ip"])

if n_total == 0:
    assessment = ("No indicators of an enabled type were retrieved "
                  "from Blocked IPs.")
else:
    bits = []
    if n_keep:
        bits.append("%d still at or above the %d%% threshold" % (n_keep, THRESHOLD))
    if n_review:
        bits.append("%d below the threshold but still flagged by FortiGuard, so "
                    "held back for review" % n_review)
    if n_clean:
        bits.append("%d decayed and safe to remove" % n_clean)
    assessment = "Of %d indicator(s): %s." % (n_total, "; ".join(bits))

result = {
    "meta": {
        "playbook": "Blocked Indicator Revalidation",
        "version": "1.2",
        "analysed_at": time.strftime("%Y-%m-%d %H:%M:%S UTC", time.gmtime()),
        "containment_mode": MODE,
        "indicator_types": ext.get("enabled_types") or [],
    },
    "config": {
        "abuse_threshold": THRESHOLD,
        "fortiguard_override": FG_OVERRIDE,
        "max_indicators": ext.get("max_indicators"),
    },
    "summary": {
        "fetched": ext.get("fetched"),
        "evaluated": n_total,
        "keep": n_keep,
        "review": n_review,
        "clean": n_clean,
        "skipped": len(ext.get("skipped") or []),
        "enabled_types": ext.get("enabled_types") or [],
        "type_counts": ext.get("type_counts") or {},
        "assessment": assessment,
    },
    "indicators": rows,
    "keep": keep,
    "review": review,
    "clean": clean,
    "actionable": {
        "keep_ips": keep_ips,
        "review_ips": review_ips,
        "clean_ips": clean_ips,
        "clean_iris": clean_iris,
    },
    "skipped": ext.get("skipped") or [],
}

print(json.dumps({
    "result": result,
    "total": n_total,
    "keep_count": n_keep,
    "review_count": n_review,
    "clean_count": n_clean,
    "indicators": rows,
    "assessment": assessment,
    "threshold": THRESHOLD,
}))
